// ----- nút đăng nhập "đuổi bắt": chưa nhập đủ tài khoản + mật khẩu thì rê chuột tới là nút nhảy tứ tung khắp khung; nhập đủ thì nút đứng yên ở giữa -----
const dock = document.getElementById('gDock'), lbl = document.getElementById('gLbl'), gLine = document.getElementById('gLine'), gAnc = document.getElementById('gAnc'), card = dock.closest('.card');
let bx = null, by = 8, lastJump = 0;
const ready = () => !!(gU.value.trim() && gP.value);
const place = (x, y) => {
  bx = x; by = y; gO.style.transform = 'translate(' + bx + 'px,' + (by - 8) + 'px)';
  const cy = dock.clientHeight / 2; gLine.setAttribute('x1', 19); gLine.setAttribute('y1', cy); gLine.setAttribute('x2', bx); gLine.setAttribute('y2', by + gO.offsetHeight / 2);
  gAnc.setAttribute('cx', bx); gAnc.setAttribute('cy', by + gO.offsetHeight / 2);
};
const center = () => { if (dock.clientWidth) place((dock.clientWidth - gO.offsetWidth) / 2, 8); };
const jump = (px, py) => {   // px, py: vị trí chuột tính theo góc trên-trái của rãnh
  const now = performance.now(); if (now - lastJump < 90) return; lastJump = now;
  const d = dock.getBoundingClientRect(), c = card.getBoundingClientRect(), bw = gO.offsetWidth, bh = gO.offsetHeight;
  const x0 = c.left - d.left + 12, x1 = c.right - d.left - bw - 12, y0 = c.top - d.top + 12, y1 = c.bottom - d.top - bh - 12;
  let best = null, bd = -1;
  for (let i = 0; i < 14; i++) { const x = x0 + Math.random() * (x1 - x0), y = y0 + Math.random() * (y1 - y0), dd = Math.hypot(x + bw / 2 - px, y + bh / 2 - py);
    if (dd > bd) { bd = dd; best = [x, y]; } if (dd > 170) break; }
  place(best[0], best[1]);
};
const refresh = () => {
  gU.parentNode.classList.toggle('ok', !!gU.value.trim()); gP.parentNode.classList.toggle('ok', !!gP.value);
  const on = ready(); if (on !== dock.classList.contains('on')) { dock.classList.toggle('on', on); lbl.textContent = on ? 'Đăng nhập' : 'Tiếp tục'; if (on) center(); }
  if (bx === null) center();
};
window.gRefresh = refresh;
gU.addEventListener('input', refresh); gP.addEventListener('input', refresh);
const gateEl = document.getElementById('gate');
gateEl.addEventListener('pointermove', e => {
  if (ready() || gO.disabled || e.pointerType === 'touch' || bx === null) return;
  const d = dock.getBoundingClientRect(), px = e.clientX - d.left, py = e.clientY - d.top, bw = gO.offsetWidth, bh = gO.offsetHeight;
  if (Math.abs(px - (bx + bw / 2)) < bw / 2 + 45 && Math.abs(py - (by + bh / 2)) < bh / 2 + 40) jump(px, py);
});
gO.addEventListener('pointerenter', e => { if (!ready() && e.pointerType !== 'touch') { const d = dock.getBoundingClientRect(); jump(e.clientX - d.left, e.clientY - d.top); } });
card.addEventListener('pointerleave', () => { setTimeout(() => { if (!ready() && !card.matches(':hover')) center(); }, 900); });
gO.addEventListener('click', e => { if (!ready()) { e.preventDefault(); dock.classList.remove('shake'); void dock.offsetWidth; dock.classList.add('shake');
  gE.textContent = 'Nhập đủ tài khoản và mật khẩu thì nút mới chịu đứng yên.'; (gU.value.trim() ? gP : gU).focus(); } });
window.addEventListener('resize', () => { if (!gateEl.hidden) center(); });
setTimeout(refresh, 0);
